pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint[] memory v) public {
        vm.assume(_tos.length > 0);
        vm.assume(v.length == _tos.length);
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        (bool success, bytes memory ret) = address(c).call(abi.encodeWithSelector(C.transfer.selector, _tos, v));
        if (success) {
            assertTrue(abi.decode(ret, (bool)));
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(address[] memory tos, uint[] memory v) public returns (bool) {
        bool preRevert = false;
        bool postRevert = false;
        try c.transfer(tos, v) { preRevert = false; } catch { preRevert = true; }
        require(msg.sender != 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        try c.transfer(tos, v) { postRevert = false; } catch { postRevert = true; }
        assert(preRevert == postRevert);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address[] memory _tos, uint[] memory v) public payable {
        require(true);
        bool reverted; try c.transfer(_tos, v) { reverted = false; } catch { reverted = true; }
        assert(!reverted ? msg.sender == c.from() : true);
    }
    receive() external payable { }
